from pathlib import Path
import datetime, hashlib, json
W=Path(__file__).resolve().parents[1]
source=W/'science/SOURCE_FINDINGS.json'
raw=source.read_bytes(); findings=json.loads(raw)
verified=[]
for s in findings['sources']:
    p=Path(s['path']); b=p.read_bytes(); lines=b.decode('utf-8-sig').splitlines()
    excerpts=[{'start_line':e['start_line'],'end_line':e['end_line'],'matches': '\n'.join(lines[e['start_line']-1:e['end_line']])==e['text']} for e in s['excerpts']]
    verified.append(dict(id=s['id'],path=str(p),sha256=hashlib.sha256(b).hexdigest(),hash_matches=hashlib.sha256(b).hexdigest()==s['sha256'],excerpts=excerpts))
assert len(verified)==12 and all(s['hash_matches'] and all(e['matches'] for e in s['excerpts']) for s in verified)
mapping=[
 dict(id='SC01',sources=['manifest_math'],scope='Inversa do ramo selecionado AρA, sob as hipóteses da fonte.',contract='Conservar identificação do ramo, parâmetros/projetores, escala/normalização e informação de fase/quadrante quando utilizada. Aproximação em floats não certifica igualdade de bytes.',not_implied='Inversão do canal não seletivo, compressão ou resistência a corrupção.',controls=['C01','C02','C05']),
 dict(id='SC02',sources=['root_transform','mirror_transform','dictionary'],scope='REFLECT/MANIFEST numéricos e quantização angular.',contract='Texto, instruções, evidências e anexos lossless exigem reconstrução dos bytes originais. Transformações aproximadas só podem ser experimentos separados, com erro declarado e original/resíduo preservados quando necessários.',not_implied='Correlação/PSNR alta não satisfaz fidelidade exata; sinal+raiz e dobra não garantem compressão.',controls=['C01','C02','C09']),
 dict(id='SC03',sources=['codec'],scope='Candidato de engenharia: modo arquivo distinto de modo tensor.',contract='Escolher formato/schema sem ambiguidade, medir envelope completo, comparar bytes diretamente e verificar digest/comprimento antes de aplicar. Modo stored ainda acrescenta cabeçalho: redução de payload não garante redução total.',not_implied='O comentário garantido por SHA256 não transforma digest em prova absoluta, autenticação ou correção de erros; disponibilidade do código não constitui aprovação.',controls=['C01','C05','C07','C09']),
 dict(id='SC04',sources=['archive','cli'],scope='Referência de contêiner com streaming, limites e caminhos.',contract='Entradas externas não herdam untrusted=False do CLI. Se adotado, revisar limites agregados/chunks, aliases de nomes, caminhos, framing, backpressure, validação final e atomicidade. A leitura registra normalização de drive/barra em _sanitize_relpath; não descrevê-la como rejeição literal de todo caminho absoluto sem teste.',not_implied='API nomeada streaming não prova baixa memória ou latência de primeiro chunk em todos os modos; modo cifrado pode bufferizar.',controls=['C04','C07','C08','C10']),
 dict(id='SC05',sources=['share_crypto_pilot','archive','operator_architecture'],scope='Separação estrutural de componentes e proposta/uso de criptografia padrão.',contract='XOR por share_id não será aceito como sigilo. Se o transporte reutilizar AEAD, auditar derivação e unicidade chave/nonce, autenticação de metadados/base/escopo e replay no protocolo completo. Não introduzir criptografia própria nesta revisão.',not_implied='Nome Túnel de Hilbert, separação de componentes ou hash não demonstra proteção quântica; proposta histórica de endpoint público não autoriza expor o novo transporte.',controls=['C03','C04','C05','C06']),
 dict(id='SC06',sources=['luminodio_element','operator_context','atlas'],scope='Afirmação do operador preservada; fonte específica de proteção não localizada na busca delimitada.',contract='Manter pedido humano de localização em aberto. A engenharia lossless pode prosseguir e ser avaliada com testes de bytes, segurança e desempenho, sem exigir confirmação pela natureza. Uma futura alegação de proteção quântica exige fonte e ponte explícitas entre objetos, hipóteses e canal.',not_implied='Não localizado não é inexistente/refutado; o artigo Z156 não substitui a prova específica e não bloqueia por si o codec de engenharia.',controls=['C11','C12']),
 dict(id='SC07',sources=['codec','archive'],scope='Identidade do formato e teto experimental informados na mensagem humana; protótipo não inspecionado.',contract='Distinguir ACOM1 legado do app do codec canônico Central por identificador inequívoco de formato/versão/layout e decoder selecionado explicitamente. Renomear só o rótulo não basta se negociação continuar ambígua. Compatibilidade e rejeição cruzada precisam de vetores congelados. 8 MiB é testcap experimental, não novo limite autorizado do app.',not_implied='Assinatura/magic semelhante não prova interoperabilidade. Testcap não autoriza reduzir PDF25MB ou demais limites existentes na integração.',controls=['C01','C07','C12']),
 dict(id='SC08',sources=['codec','archive','operator_context'],scope='Condições para uma eventual integração negociada.',contract='Negociar capacidades autenticadas, versão, base e limites antes de admitir a unidade. Medir ganho end-to-end e segurança no caminho proposto; registrar critério de seleção antes da conclusão. Modo não suportado recusa antes de efeito ou usa baseline explicitamente negociado. Nunca reenviar remotamente uma unidade de resultado incerto para experimentar outro codec. Rollback de configuração não repete operação.',not_implied='Este mapa não habilita integração, não aprova protótipo e não promete redução de tokens ou latência.',controls=['C03','C04','C06','C08','C09','C10','C12'])
]
report=dict(schema='iald.science_contract_review.v1',status='SOURCE_TRACEABILITY_VERIFIED_CONTRACT_PROPOSED',reviewer='codex-readability-reviewer',unit='F9.ACOM_SIGNAL_TRANSPORT_20261021',created_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_findings={'path':str(source),'sha256':hashlib.sha256(raw).hexdigest()},criteria={'path':str(W/'review/CRITERIA.json'),'sha256':hashlib.sha256((W/'review/CRITERIA.json').read_bytes()).hexdigest()},verified_sources=verified,mapping=mapping,findings=[],interpretation_notes=['Verificados hashes e correspondência literal dos trechos nas12fontes; resultados científicos históricos não recalculados ou promovidos.', 'Levantamento dirigido não é busca exaustiva; referência humana da prova específica permanece pendente.', 'Comentários de fonte são afirmações a qualificar pelo código/contrato, não certificados de segurança.', 'Nenhum requisito de confirmação física para demonstrar round-trip digital; nenhuma proteção quântica alegada.'],pending=['Congelamento do protótipo e manifesto de hashes pelo autor, incluindo identidade renomeada do formato.', 'Resultados offline de fidelidade, isolamento, idempotência, limites, streaming e comparação de ganho com overhead.', 'Plano negociado de integração e rollback, caso haja ganho/segurança medidos e escopo autorizado.', 'Fonte específica do operador para a alegação luminídio/Hilbert; pendência de fundamentação da alegação, separada da engenharia.'],prototype_review='WAITING_FOR_FREEZE_NOT_READ_OR_EXECUTED',integration_approved=False,automatic_acceptance=False,execution={'source_reads_only':True,'tests_run':0,'remote_calls':0,'runtime_changed':False,'memory_changed':False,'board_changed':False})
out=W/'review/SCIENCE_CONTRACT.json'
if out.exists():
    old=out.read_bytes();bak=out.with_name(out.name+'.bak_'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f'));bak.write_bytes(old);assert bak.read_bytes()==old
data=json.dumps(report,ensure_ascii=False,indent=2).encode('utf-8');tmp=out.with_suffix('.json.tmp');tmp.write_bytes(data);assert tmp.read_bytes()==data;tmp.replace(out)
print(json.dumps({'status':report['status'],'sources':len(verified),'mappings':len(mapping),'path':str(out),'sha256':hashlib.sha256(data).hexdigest()},ensure_ascii=False))
